    about_peter_bio: 'Peter is not scared of risky ideas. He listens, asks and acts immediately on any Gavelling related feedback. He is not just a figure with good ideas, but someone who has actively trained his own delegation to win over 100 awards in a single year. Ultimately, fun, adventure and creativity knows no bounds for Peter, having travelled to over 40 countries at 22.',
