    about_christian_bio: 'Christian is constantly looking for change and progress; having lived in 9 countries at 21 years old. He applies this same mindset to Gavelling: voicing new ideas, taking feedback, and looking for positive change. His constant journey for new challenges led him to train delegates across continents to win awards at a 90% rate in global conferences.',
