    about_peter_role: 'Desarrollo de Negocio y Frontend',
    about_peter_bio: 'Peter no le teme a las ideas arriesgadas. Escucha, pregunta y actúa de inmediato ante cualquier comentario sobre Gavelling. No es solo una figura con buenas ideas, sino alguien que ha entrenado activamente a su propia delegación para ganar más de 100 premios en un solo año. En definitiva, la diversión, la aventura y la creatividad no tienen límites para Peter, habiendo viajado a más de 40 países a los 22 años.',
    about_christian_role: 'Desarrollo de Negocio y Backend',
    about_christian_bio: 'Christian busca constantemente el cambio y el progreso; habiendo vivido en 9 países a los 21 años. Aplica esta misma mentalidad a Gavelling: aportando nuevas ideas, recibiendo comentarios y buscando el cambio positivo. Su constante búsqueda de nuevos desafíos lo llevó a entrenar delegados en distintos continentes para ganar premios en conferencias globales a una tasa del 90%.',
