    about_peter_role: 'Développement Commercial et Frontend',
    about_peter_bio: "Peter n'a pas peur des idées risquées. Il écoute, questionne et agit immédiatement sur tout retour lié à Gavelling. Ce n'est pas seulement une figure avec de bonnes idées, mais quelqu'un qui a activement entraîné sa propre délégation à remporter plus de 100 prix en une seule année. En fin de compte, la joie, l'aventure et la créativité ne connaissent aucune limite pour Peter, qui a voyagé dans plus de 40 pays à 22 ans.",
    about_christian_role: 'Développement Commercial et Backend',
    about_christian_bio: "Christian est constamment à la recherche de changement et de progrès ; ayant vécu dans 9 pays à 21 ans. Il applique la même mentalité à Gavelling : en apportant de nouvelles idées, en recevant des retours et en cherchant le changement positif. Sa quête constante de nouveaux défis l'a amené à entraîner des délégués sur plusieurs continents pour remporter des prix avec un taux de réussite de 90 % dans des conférences mondiales.",
