    about_btn_close: 'إغلاق',
    about_peter_role: 'تطوير الأعمال والواجهة الأمامية',
    about_peter_bio: 'بيتر لا يخشى الأفكار الجريئة. يستمع ويسأل ويتصرّف فوراً بناءً على أي ملاحظات تتعلق بـ Gavelling. وهو ليس مجرد صاحب أفكار جيدة، بل شخص درّب وفده بنفسه للفوز بأكثر من 100 جائزة في عام واحد. وفي النهاية، لا حدود للمتعة والمغامرة والإبداع لدى بيتر، الذي سافر إلى أكثر من 40 دولة في سن الثانية والعشرين.',
    about_christian_role: 'تطوير الأعمال والواجهة الخلفية',
    about_christian_bio: 'كريستيان يبحث باستمرار عن التغيير والتقدّم؛ إذ عاش في 9 دول في سن الحادية والعشرين. ويطبّق العقلية نفسها على Gavelling: يطرح أفكاراً جديدة، ويتقبّل الملاحظات، ويبحث عن التغيير الإيجابي. وقد قاده سعيه الدائم لتحديات جديدة إلى تدريب مندوبين عبر القارات للفوز بالجوائز بمعدل 90% في المؤتمرات العالمية.',
